    """Find test files that target the touched modules.

    Strategy: for every changed ``<pkg>/<module>.py`` (ignoring ``__init__``),
    look for ``test_<module>.py`` anywhere under the tests tree. We match on
    stem name, which is the repo's naming convention (``gatekeeper`` ↔
    ``test_gatekeeper.py``). Returns the real path list; empty => ruff-only.
    """
    stems = _collect_stems(changed_files)
    if not stems:
        return []
    return _find_matched_tests(stems)


def _collect_stems(changed_files: list[str]) -> set[str]:
    """Collect module stems from changed files for test matching."""
    if not changed_files:
        return set()
    tests_root = os.path.normpath(TESTS_DIR)
    if not os.path.isdir(tests_root):
        return set()
    stems: set[str] = set()
    for f in changed_files:
        stem = _file_stem(f)
        if stem:
            stems.add(stem)
    return stems


def _file_stem(filepath: str) -> str | None:
    """Return the stem to use for test matching, or None if not a Python file."""
    base = os.path.basename(filepath)
    if base == "__init__.py":
        return os.path.basename(os.path.dirname(filepath))
    stem, ext = os.path.splitext(base)
    return stem if ext == ".py" else None


def _find_matched_tests(stems: set[str]) -> list[str]:
    """Walk the tests tree and return sorted unique test files matching the stems."""
    tests_root = os.path.normpath(TESTS_DIR)
    matched: list[str] = []
    for root, _dirs, files in os.walk(tests_root):
        for name in files:
            if _is_matching_test(name, stems):
                matched.append(os.path.join(root, name))
    return sorted(set(matched))


def _is_matching_test(name: str, stems: set[str]) -> bool:
    """Return True if *name* is a ``test_<module>.py`` file whose module stem is in *stems*."""
    stem, ext = os.path.splitext(name)
    return ext == ".py" and stem.startswith("test_") and stem[5:] in stems"}

